<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

$pdo=Database::connection();Auth::enforceCurrentUser();$tenantId=Auth::tenantId();
function em_money(int|float|string$cents):string{return'R$ '.number_format(((int)$cents)/100,2,',','.');}
function em_csrf():string{return Security::e(Security::csrfToken());}
function em_post_csrf():void{if(!Security::validateCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Sessão expirada. Atualize a página.');}}
function em_base_path():string{$script=(string)($_SERVER['SCRIPT_NAME']??'');$dir=$script!==''?str_replace('\\','/',dirname($script)):'';if($dir==='/'||$dir==='.')$dir='';$configured=(string)env('APP_URL','');$path=$configured!==''?(string)(parse_url($configured,PHP_URL_PATH)??''):'';$path=rtrim($path,'/');if($path==='/')$path='';return$dir!==''?$dir:$path;}
function em_url(string$path=''):string{$base=em_base_path();if($path==='')return$base!==''?$base.'/':'/';if(!str_starts_with($path,'/'))$path='/'.$path;if($base!==''&&($path===$base||str_starts_with($path,$base.'/')))return$path;return$base.$path;}
function em_go(string$route,array$params=[]):never{$params=['route'=>$route]+$params;header('Location: '.em_url('/?'.http_build_query($params)));exit;}
function em_slug(string$value):string{$v=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value)?:$value;$v=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',$v)??'','-'));return$v?:bin2hex(random_bytes(3));}
function em_selected(mixed$a,mixed$b):string{return(string)$a===(string)$b?' selected':'';}
function em_checked(bool|int|string$v):string{return(bool)$v?' checked':'';}
function em_flash(?string$type=null,?string$message=null):?array{if($type&&$message){$_SESSION['_flash']=[$type,$message];return null;}$f=$_SESSION['_flash']??null;unset($_SESSION['_flash']);return$f;}
function em_can_nav(string$permission):bool{if($permission==='superadmin.only')return Auth::role()==='super_admin';return$permission==='reports.any'?(Auth::can('reports.view')||Auth::can('reports.own')):Auth::can($permission);}
function em_role_label(?string$role):string{return Auth::roleLabel($role);}
function em_status_label(?string$status):string{return match($status){'active'=>'Ativo','inactive'=>'Inativo','blocked'=>'Bloqueado','pending'=>'Pendente','confirmed'=>'Confirmado','preparing'=>'Em preparo','ready'=>'Pronto','out_for_delivery'=>'Saiu para entrega','completed'=>'Concluído','cancelled'=>'Cancelado','paid'=>'Pago','unpaid'=>'Não pago','partial'=>'Parcial','partially_refunded'=>'Reembolso parcial','refunded'=>'Reembolsado','fulfilled'=>'Entregue','reserved'=>'Reservado','checked_in'=>'Check-in realizado',default=>$status?:'—'};}
function em_initials(string$name):string{$parts=preg_split('/\s+/',trim($name))?:[];$a=$parts[0]??'E';$b=count($parts)>1?$parts[array_key_last($parts)]:'';return mb_strtoupper(mb_substr($a,0,1).mb_substr($b,0,1));}
function em_module_enabled(string$key):bool{static$cache=[];$tenant=Auth::tenantId();if(!$tenant)return true;$ck=$tenant.':'.$key;if(array_key_exists($ck,$cache))return$cache[$ck];try{$s=Database::connection()->prepare('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key=? LIMIT 1');$s->execute([$tenant,$key]);$v=$s->fetchColumn();return$cache[$ck]=$v===false?true:(bool)$v;}catch(Throwable){return$cache[$ck]=true;}}
function em_nav():array
{
    $r=Auth::role();if($r==='kitchen')return[['kitchen','Tela da cozinha','orders.kitchen','kitchen']];if($r==='delivery')return[['my-deliveries','Minhas entregas','orders.delivery','delivery']];if($r==='counter')return[['pos','Nova venda','orders.create','pos'],['counter-orders','Minhas vendas','counter.orders','orders'],['fulfillment','Retiradas','fulfillment.manage','scan']];if($r==='cashier')return[['pos','PDV / Balcão','orders.create','pos'],['fulfillment','Retiradas','fulfillment.manage','scan'],['orders','Pedidos','orders.view','orders'],['cash','Caixa','payments.manage','cash'],['customers','Clientes','customers.manage','users'],['notifications','Notificações','notifications.view','bell']];if($r==='waiter')return[['restaurant','Mesas e comandas','tables.manage','tables'],['pos','Lançar pedido','orders.create','pos'],['orders','Pedidos','orders.view','orders'],['notifications','Chamadas e avisos','notifications.view','bell']];if($r==='promoter')return[['guests','Convidados','guests.manage','users'],['reports','Meus relatórios','reports.any','chart']];
    $items=[[$r==='super_admin'?'superadmin':'dashboard',$r==='super_admin'?'Super ADM':'Visão geral',$r==='super_admin'?'superadmin.only':'dashboard',$r==='super_admin'?'building':'home',null],['pos','PDV / Balcão','orders.create','pos','menu'],['fulfillment','Retiradas','fulfillment.manage','scan','menu'],['products','Cardápio e produtos','catalog.manage','menu','menu'],['orders','Pedidos','orders.view','orders',null],['delivery','Delivery','delivery.assign','delivery','delivery'],['kitchen','Cozinha / KDS','orders.kitchen','kitchen','restaurant'],['restaurant','Mesas e comandas','tables.manage','tables','restaurant'],['cash','Caixa','payments.manage','cash',null],['customers','Clientes e fidelidade','customers.manage','users','loyalty'],['coupons','Cupons','coupons.manage','coupon','menu'],['events','Eventos','events.manage','calendar','events'],['tickets','Ingressos / Check-in','tickets.manage','ticket','events'],['guests','Convidados','guests.manage','users','events'],['promoters','Promotores','promoters.manage','promoter','events'],['payments','Pagamentos','payments.manage','card',null],['gateways','Gateways e NFC','gateways.manage','nfc',null],['units','Unidades / filiais','units.manage','building',null],['users','Equipe e permissões','users.manage','team',null],['notifications','Notificações','notifications.view','bell',null],['reports','Relatórios','reports.any','chart',null],['audit','Auditoria','audit.view','audit',null],['settings-hub','Configurações','settings.manage','settings',null]];return array_values(array_filter($items,fn($i)=>$i&&($i[4]===null||em_module_enabled($i[4]))));
}
