0M7 8h2M7 12h2M7 16h2M15 12h2M15 16h2"/>','bell'=>'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6"/>',default=>'<circle cx="12" cy="12" r="8"/>'};return'<svg viewBox="0 0 24 24" aria-hidden="true">'.$paths.'</svg>';}
function em_workspace_subtitle():string{return match(Auth::role()){'counter'=>'Venda e retirada de produtos','cashier'=>'Vendas, recebimentos e caixa','waiter'=>'Mesas, comandas e atendimento','kitchen'=>'Fila de preparo em tempo real','delivery'=>'Entregas atribuídas ao seu usuário','promoter'=>'Convidados e resultados da sua operação',default=>'Gerencie sua operação em um só lugar'};}
function em_header(string$title,string$active):void
{
    $flash=em_flash();$name=Auth::name();$role=em_role_label(Auth::role());$units=[];$unitName='';if(Auth::tenantId()){try{$units=Auth::availableUnits();$uid=Auth::unitId();foreach($units as$u)if((int)$u['id']===$uid)$unitName=(string)$u['name'];}catch(Throwable){}}
    $unread=0;if(Auth::tenantId()&&Auth::can('notifications.view'))try{$s=Database::connection()->prepare('SELECT COUNT(*) FROM notifications WHERE tenant_id=? AND status="unread" AND (target_user_id IS NULL OR target_user_id=?)');$s->execute([Auth::tenantId(),Auth::id()]);$unread=(int)$s->fetchColumn();}catch(Throwable){}
    ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#6d4aff"><title><?= Security::e($title) ?> — EventMenu Premium</title><link rel="manifest" href="<?= Security::e(em_url('/manifest.webmanifest')) ?>"><link rel="stylesheet" href="<?= Security::e(em_url('/assets/app.css')) ?>?v=92legacy3"><style>.top-search{display:flex;align-items:center;gap:6px}.top-search input{width:190px}.notification-pill{position:relative}.notification-pill b{position:absolute;right:-6px;top:-8px;background:#ef4444;color:#fff;border-radius:999px;min-width:18px;height:18px;font-size:10px;display:grid;place-items:center}.theme-dark{--bg:#0e1118;--surface:#151a24;--surface-2:#1c2230;--text:#eef1f8;--muted:#9ca4b6;--line:#2b3344}.theme-dark body,.theme-dark .content{background:var(--bg);color:var(--text)}.theme-dark .card,.theme-dark .topbar{background:var(--surface);color:var(--text);border-color:var(--line)}@media(max-width:900px){.top-search{display:none}.unit-switch{max-width:130px}}</style></head><body><div class="mobile-bar"><button class="mobile-menu-btn" type="button" id="mobileMenuBtn" aria-label="Abrir menu"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button><div class="mobile-brand">EventMenu <span>Premium</span></div><div class="mobile-avatar"><?= Security::e(em_initials($name)) ?></div></div><div class="sidebar-overlay" id="sidebarOverlay"></div><div class="layout"><aside class="sidebar" id="sidebar"><div class="brand-wrap"><div class="brand-mark">EM</div><div class="brand">EventMenu <span>Premium</span></div></div><div class="sidebar-label"><?= Security::e($role) ?><?= $unitName?'<br><small>'.Security::e($unitName).'</small>':'' ?></div><nav class="nav"><?php foreach(em_nav()as$item):[$route,$label,$permission,$icon]=$item;if(!em_can_nav($permission))continue;?><a class="<?= $active===$route?'active':'' ?>" href="<?= Security::e(em_url('/?route='.$route)) ?>"><span class="nav-icon"><?= em_icon($icon) ?></span><span><?= Security::e($label) ?></span></a><?php endforeach;?></nav><div class="sidebar-foot"><div class="user-avatar"><?= Security::e(em_initials($name)) ?></div><div class="sidebar-user"><strong><?= Security::e($name) ?></strong><span><?= Security::e($role) ?></span></div><a class="logout-link" href="<?= Security::e(em_url('/?route=logout')) ?>">Sair</a></div></aside><main class="content"><header class="topbar"><div class="topbar-copy"><h1><?= Security::e($title) ?></h1><div class="topbar-subtitle"><?= Security::e(em_workspace_subtitle()) ?></div></div><div class="topbar-actions"><?php if(count($units)>1):?><form method="post" action="<?= Security::e(em_url('/?route=units')) ?>" class="actions"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="select"><select class="unit-switch" name="unit_id" onchange="this.form.submit()"><option value="0">Todas as unidades</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= em_selected(Auth::unitId(),$u['id']) ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></form><?php endif;?><?php if(Auth::tenantId()&&(Auth::can('dashboard')||Auth::can('orders.view')||Auth::can('counter.orders'))):?><form class="top-search" method="get"><input type="hidden" name="route" value="search"><input name="q" placeholder="Buscar..." aria-label="Busca global"><button class="secondary" title="Buscar">⌕</button></form><?php endif;?><?php if(Auth::can('notifications.view')):?><a class="button secondary notification-pill" href="<?= Security::e(em_url('/?route=notifications')) ?>">Avisos<?php if($unread):?><b><?= min(99,$unread) ?></b><?php endif;?></a><?php endif;?><button class="button secondary" type="button" id="themeToggle" title="Alternar tema">◐</button><span class="workspace-chip"><?= Security::e($role) ?></span></div></header><?php if($flash):?><div class="alert <?= Security::e($flash[0]) ?>"><?= Security::e($flash[1]) ?></div><?php endif;?><?php
}
function em_footer():void{$sw=em_url('/sw.js');?><script>(()=>{const root=document.documentElement,body=document.body,btn=document.getElementById('mobileMenuBtn'),overlay=document.getElementById('sidebarOverlay'),theme=document.getElementById('themeToggle');const close=()=>body.classList.remove('nav-open');if(btn)btn.addEventListener('click',()=>body.classList.toggle('nav-open'));if(overlay)overlay.addEventListener('click',close);document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',close));window.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName||'')){e.preventDefault();document.querySelector('.top-search input')?.focus();}});const apply=v=>root.classList.toggle('theme-dark',v==='dark');const saved=localStorage.getItem('eventmenu-theme')||'light';apply(saved);theme?.addEventListener('click',()=>{const v=root.classList.contains('theme-dark')?'light':'dark';localStorage.setItem('eventmenu-theme',v);apply(v);});if('serviceWorker'in navigator){navigator.serviceWorker.register('<?= Security::e($sw) ?>').catch(()=>{});}})();</script></main></div></body></html><?php }
function em_require_tenant():int{$id=Auth::tenantId();if(!$id){http_response_code(403);exit('Selecione uma empresa no Super ADM.');}return$id;}
